import{c as d,Q as e,j as o,m as r}from"./chunks/framework.BXc4yaFE.js";const u=JSON.parse('{"title":"模型 × effort 難題組重測（2026-07-17，鑑別力版）","description":"","frontmatter":{},"headers":[],"relativePath":"research/reports/2026-07-17-model-tier-effort-hard-probe.md","filePath":"research/reports/2026-07-17-model-tier-effort-hard-probe.md","lastUpdated":1785909234000}'),a={name:"research/reports/2026-07-17-model-tier-effort-hard-probe.md"};function l(n,t,i,s,h,f){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="模型-×-effort-難題組重測-2026-07-17-鑑別力版" tabindex="-1">模型 × effort 難題組重測（2026-07-17，鑑別力版） <a class="header-anchor" href="#模型-×-effort-難題組重測-2026-07-17-鑑別力版" aria-label="Permalink to &quot;模型 × effort 難題組重測（2026-07-17，鑑別力版）&quot;">​</a></h1><blockquote><p>Workflow <code>wf_5f686adf-73d</code>；前輪（同日 easy 版）全組態天花板無鑑別力 → 本輪 4 難題：H1 asyncio 假 race 陷阱（正解=不是 race）、H2 Conway 模式期望值（=20）、H3 Python 語義精確輸出（print 引數別名陷阱）、H4 O(1) 多重集設計。n=1/組態。</p></blockquote><h2 id="結果-機械計分" tabindex="-1">結果（機械計分） <a class="header-anchor" href="#結果-機械計分" aria-label="Permalink to &quot;結果（機械計分）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>組態</th><th>H1 陷阱</th><th>H1 缺陷廣度</th><th>H2=20</th><th>H3 全對</th><th>正確率</th></tr></thead><tbody><tr><td>fable-low</td><td>✅</td><td><strong>6</strong></td><td>✅</td><td>✅</td><td>4/4</td></tr><tr><td>fable-medium</td><td>✅</td><td><strong>7</strong></td><td>✅</td><td>✅</td><td>4/4</td></tr><tr><td>opus-low</td><td>✅</td><td>5</td><td>✅</td><td>✅</td><td>4/4</td></tr><tr><td>opus-medium</td><td>✅</td><td>5</td><td>✅</td><td>✅</td><td>4/4</td></tr><tr><td>sonnet-low</td><td>✅</td><td>3</td><td>✅</td><td>❌（<code>[1] [1, 2]</code>）</td><td>3/4</td></tr><tr><td>sonnet-medium</td><td>✅</td><td>5</td><td>✅</td><td>✅</td><td>4/4</td></tr><tr><td>haiku-low</td><td>✅</td><td>3</td><td>✅</td><td>❌（同上）</td><td>3/4</td></tr><tr><td>haiku-medium</td><td>✅</td><td>3</td><td>✅</td><td>✅</td><td>4/4</td></tr></tbody></table><p>H3 失分點一致：sonnet/haiku 在 low 漏掉「print 兩引數先求值、預設參數同一 list → 兩者皆 <code>[1, 2]</code>」的別名效應。</p><h2 id="判讀-n-1-資料表級信心" tabindex="-1">判讀（n=1，資料表級信心） <a class="header-anchor" href="#判讀-n-1-資料表級信心" aria-label="Permalink to &quot;判讀（n=1，資料表級信心）&quot;">​</a></h2><ol><li><strong>frontier/ceiling 帶（fable/opus）：low 即安全</strong>——難題正確率不因 effort 降低而掉；medium 只加廣度（fable 6→7 缺陷）。</li><li><strong>quality/cost 帶（sonnet/haiku）：low 有微妙語義正確性風險，medium 修復</strong>——與前輪「low 即天花板」結論<strong>修正合併</strong>：easy 任務全帶 low 安全；tricky 語義任務 sonnet/haiku 需 medium。</li><li><strong>Fable-low 定位確認（兩輪一致）</strong>：正確率 = opus 任一檔、缺陷發現廣度高於 opus-medium——「Fable-low ≈ Opus medium 帶、廣度更優」。</li><li>委派 effort 路由啟示（併入 delegation-protocol 既有 n=1 行的後續證據）：<code>fable/opus → low 預設；sonnet/haiku → 機械任務 low、語義敏感任務 medium</code>。</li></ol><h2 id="升級條件" tabindex="-1">升級條件 <a class="header-anchor" href="#升級條件" aria-label="Permalink to &quot;升級條件&quot;">​</a></h2><p>同題組（或同難度新題）重跑 1 次結論一致 → 夠格改寫 delegation-protocol 資料點為 n=2 並考慮進 model-profiles §2。</p>',9)])])}const m=d(a,[["render",l]]);export{u as __pageData,m as default};
